WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Primary endpoint" AS source_value FROM clinical_trials
WHERE "Priamry Multiple, composite, or co-primary endpoints?" = 'Yes'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_endpoint_components(source_value) AS "components"
FROM base;
